  1	import java.io.PrintStream;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	
  6	final class MST {
  7	    private static final int NO_EDGE = 0;
  8	    private static final int ROOT_PARENT = -1;
  9	    private static final int START_VERTEX = 0;
 10	    private static final int[][] SAMPLE_GRAPH = {
 11	        { 0, 2, 0, 6, 0 },
 12	        { 2, 0, 3, 8, 5 },
 13	        { 0, 3, 0, 0, 7 },
 14	        { 6, 8, 0, 0, 9 },
 15	        { 0, 5, 7, 9, 0 }
 16	    };
 17	
 18	    private MST() {}
 19	
 20	    record Edge(int from, int to, int weight) {}
 21	
 22	    record Result(List<Edge> edges, int totalWeight) {
 23	        Result {
 24	            edges = List.copyOf(edges);
 25	        }
 26	    }
 27	
 28	    private static final class Graph {
 29	        private final int[][] adjacencyMatrix;
 30	
 31	        Graph(int[][] adjacencyMatrix) {
 32	            validateAdjacencyMatrix(adjacencyMatrix);
 33	            this.adjacencyMatrix = adjacencyMatrix;
 34	        }
 35	
 36	        int vertexCount() {
 37	            return adjacencyMatrix.length;
 38	        }
 39	
 40	        int edgeWeight(int from, int to) {
 41	            return adjacencyMatrix[from][to];
 42	        }
 43	
 44	        boolean hasEdge(int from, int to) {
 45	            return edgeWeight(from, to) != NO_EDGE;
 46	        }
 47	    }
 48	
 49	    private static final class PrimState {
 50	        final int[] parent;
 51	        final int[] bestEdgeWeight;
 52	        final boolean[] includedInMst;
 53	
 54	        PrimState(int vertexCount) {
 55	            this.parent = new int[vertexCount];
 56	            this.bestEdgeWeight = new int[vertexCount];
 57	            this.includedInMst = new boolean[vertexCount];
 58	            Arrays.fill(bestEdgeWeight, Integer.MAX_VALUE);
 59	            bestEdgeWeight[START_VERTEX] = 0;
 60	            parent[START_VERTEX] = ROOT_PARENT;
 61	        }
 62	    }
 63	
 64	    private static int selectNextVertex(PrimState state) {
 65	        int minValue = Integer.MAX_VALUE;
 66	        int minIndex = -1;
 67	
 68	        for (int vertex = 0; vertex < state.includedInMst.length; vertex++) {
 69	            if (!state.includedInMst[vertex] && state.bestEdgeWeight[vertex] < minValue) {
 70	                minValue = state.bestEdgeWeight[vertex];
 71	                minIndex = vertex;
 72	            }
 73	        }
 74	
 75	        return minIndex;
 76	    }
 77	
 78	    private static void validateAdjacencyMatrix(int[][] graph) {
 79	        if (graph == null) {
 80	            throw new IllegalArgumentException("Graph must not be null.");
 81	        }
 82	
 83	        if (graph.length == 0) {
 84	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
 85	        }
 86	
 87	        for (int rowIndex = 0; rowIndex < graph.length; rowIndex++) {
 88	            int[] row = graph[rowIndex];
 89	            if (row == null) {
 90	                throw new IllegalArgumentException("Graph rows must not be null.");
 91	            }
 92	
 93	            if (row.length != graph.length) {
 94	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
 95	            }
 96	
 97	            for (int columnIndex = rowIndex + 1; columnIndex < graph.length; columnIndex++) {
 98	                if (row[columnIndex] != graph[columnIndex][rowIndex]) {
 99	                    throw new IllegalArgumentException(
100	                        "Graph must represent an undirected adjacency matrix."
101	                    );
102	                }
103	            }
104	        }
105	    }
106	
107	    private static Result buildResult(PrimState state, Graph graph) {
108	        List<Edge> edges = new ArrayList<>();
109	        int totalWeight = 0;
110	
111	        for (int vertex = 1; vertex < graph.vertexCount(); vertex++) {
112	            int from = state.parent[vertex];
113	            int weight = graph.edgeWeight(from, vertex);
114	
115	            edges.add(new Edge(from, vertex, weight));
116	            totalWeight += weight;
117	        }
118	
119	        return new Result(edges, totalWeight);
120	    }
121	
122	    private static void relaxOutgoingEdges(Graph graph, PrimState state, int currentVertex) {
123	        state.includedInMst[currentVertex] = true;
124	
125	        for (int neighbor = 0; neighbor < graph.vertexCount(); neighbor++) {
126	            int edgeWeight = graph.edgeWeight(currentVertex, neighbor);
127	
128	            if (graph.hasEdge(currentVertex, neighbor) && !state.includedInMst[neighbor]
129	                && edgeWeight < state.bestEdgeWeight[neighbor]) {
130	                state.parent[neighbor] = currentVertex;
131	                state.bestEdgeWeight[neighbor] = edgeWeight;
132	            }
133	        }
134	    }
135	
136	    static Result computeMinimumSpanningTree(int[][] graph) {
137	        return computeMinimumSpanningTree(new Graph(graph));
138	    }
139	
140	    private static Result computeMinimumSpanningTree(Graph graph) {
141	        int vertexCount = graph.vertexCount();
142	        PrimState state = new PrimState(vertexCount);
143	
144	        for (int count = 0; count < vertexCount - 1; count++) {
145	            int currentVertex = selectNextVertex(state);
146	
147	            if (currentVertex == -1) {
148	                throw new IllegalStateException("Graph must be connected.");
149	            }
150	
151	            relaxOutgoingEdges(graph, state, currentVertex);
152	        }
153	
154	        return buildResult(state, graph);
155	    }
156	
157	    static String renderResult(Result result) {
158	        StringBuilder output = new StringBuilder("Edge \tWeight\n");
159	        for (Edge edge : result.edges()) {
160	            output.append(edge.from())
161	                .append(" - ")
162	                .append(edge.to())
163	                .append('\t')
164	                .append(edge.weight())
165	                .append('\n');
166	        }
167	        return output.toString();
168	    }
169	
170	    static void printResult(PrintStream out, Result result) {
171	        out.print(renderResult(result));
172	    }
173	
174	    public static void main(String[] args)
175	    {
176	        Result result = computeMinimumSpanningTree(SAMPLE_GRAPH);
177	        printResult(System.out, result);
178	    }
179	}
